<script setup lang="ts">
import {ref,computed,defineAsyncComponent} from 'vue'
import HostConnect from './HostConnect.vue'
import HostTrafficFields from './HostTrafficFields.vue'
import {hostDraft,hostPayload,hostTrafficBytes,hostModes} from './hostBilling'
const HostTraffic=defineAsyncComponent(()=>import('./HostTraffic.vue'))
const trafficHost=ref<Record<string,any>|null>(null)
const EngineManager=defineAsyncComponent(()=>import('./EngineManager.vue'))
const kernelHost=ref<Record<string,any>|null>(null)
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,hosts:Row[]}>()
const emit=defineEmits<{changed:[],configure:[id:string]}>()
const editing=ref<Row|null>(null),connecting=ref<Row|null>(null),removing=ref<Row|null>(null),busy=ref(false),error=ref(''),search=ref('')
const rows=computed(()=>props.hosts.filter(h=>(h.name+' '+h.address+' '+h.provider).toLowerCase().includes(search.value.toLowerCase())))
const online=(h:Row)=>h.online===true||Boolean(h.last_seen&&Date.now()-new Date(h.last_seen).getTime()<90000)
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();emit('changed')}catch(e){error.value=String(e)}finally{busy.value=false}}
function save(){const h=editing.value;if(!h)return;void run(async()=>{const saved=await props.api('hosts'+(h.id?'/'+h.id:''),h.id?'PATCH':'POST',{name:h.name,provider:h.provider,address:h.address,traffic:hostPayload(h.billing)});editing.value=null;if(!h.id)connecting.value={id:saved.id,name:h.name}})}
function connection(h:Row){const paused=!h.connection_paused;if(paused&&!window.confirm('暂停管理会停止这台主机由星枢托管的代理，Agent 继续发送心跳与流量；恢复后自动重新下发。继续？'))return;void run(async()=>{await props.api('hosts/'+h.id+'/connection','POST',{paused})})}
function remove(){const h=removing.value;if(!h)return;void run(async()=>{await props.api('hosts/'+h.id+(h.agent_version?'/retirement':''),h.agent_version?'POST':'DELETE',h.agent_version?{}:undefined);removing.value=null})}
</script>
<template>
<section class="panel publish-card"><div class="section-heading"><div><h2>你的服务器</h2><p class="muted">添加主机后，复制接入命令到该 VPS 执行即可。Agent 主动出站连接，无需开放管理端口。暂停管理会停止托管代理，心跳保留；恢复后在线 Agent 自动同步，离线主机需先恢复网络或服务。</p></div><button class="primary" @click="editing={name:'',provider:'',address:'',billing:hostDraft()}">＋ 连接新主机</button></div><input v-model="search" class="console-search" placeholder="搜索名称、地址或服务商" aria-label="搜索主机"><p v-if="error" class="error" role="alert">{{error}}</p>
<div class="host-card-grid"><article v-for="h in rows" :key="h.id" class="server-card"><header class="server-heading"><div class="server-title"><span class="server-icon">▣</span><div><h3>{{h.name}}</h3><p>{{h.address}}</p></div></div><span :class="['status',online(h)&&!h.connection_paused?'succeeded':'pending']">{{h.retire_state?'等待远端卸载 · '+h.retire_state:h.connection_paused?'管理已暂停':online(h)?'已连接':'未连接'}}</span></header><div class="server-meta"><span>{{h.provider}}</span><span>{{h.platform||'等待安装'}}</span><span>Agent {{h.agent_version||'—'}}</span></div><small class="host-control-origin">控制地址：{{h.control_origin||'等待新版 Agent 回报'}}</small><div class="host-quota"><div class="quota-head"><strong>{{h.traffic?.quota_bytes?hostTrafficBytes(h.traffic.remaining_bytes):'不限额'}}</strong><small>{{hostModes[h.traffic?.mode??'both']}}</small></div><progress v-if="h.traffic?.quota_bytes" :max="h.traffic.quota_bytes" :value="h.traffic.used_bytes"></progress><small>已用 {{hostTrafficBytes(h.traffic?.used_bytes)}} / {{h.traffic?.quota_bytes?hostTrafficBytes(h.traffic.quota_bytes):'未设额度'}}</small><small :class="{error:!h.traffic?.fresh}">流量采样：{{h.traffic?.fresh?'最新采样':'等待 / 已断报'}}{{h.traffic?.last_sample_at?' · '+new Date(h.traffic.last_sample_at).toLocaleTimeString():''}}{{h.traffic?.quality==='gap'?' · 需核对校准':''}}</small></div><div class="server-actions"><button class="primary" @click="emit('configure',h.id)">配置协议 →</button><button class="text-button" @click="trafficHost=h">主机流量</button><button class="text-button" @click="kernelHost=h">内核版本</button><button v-if="h.agent_version" class="text-button" :disabled="busy" @click="connection(h)">{{h.connection_paused?'恢复管理':'暂停管理'}}</button><button class="text-button" @click="connecting=h">{{h.agent_version?'连接 / 恢复':'接入命令'}}</button><button class="text-button" @click="editing={...h,billing:hostDraft(h.traffic??{})}">编辑</button><button class="text-button danger" @click="removing=h">删除</button></div></article></div><div v-if="!rows.length" class="console-empty">还没有主机。连接第一台 VPS，开始配置协议。</div>
</section>
<HostTraffic v-if="trafficHost" :host="trafficHost" :api="api" @close="trafficHost=null" @changed="emit('changed')"/>
<EngineManager v-if="kernelHost" :host="kernelHost" :api="api" @close="kernelHost=null"/>
<HostConnect v-if="connecting" :host="connecting as {id:string,name:string,agent_version?:string,last_seen?:string}" :api="api" @close="connecting=null" @connected="emit('changed')"/>
<div v-if="editing" class="modal-backdrop" @keydown.esc="editing=null"><form class="modal single-column-editor" role="dialog" aria-modal="true" aria-label="主机信息" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑主机':'连接新主机'}}</h2><button type="button" class="secondary" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" role="alert" class="error">{{error}}</p><div class="fields"><label>主机名称<input v-model="editing.name" required maxlength="100"></label><label>服务商 / 标签<input v-model="editing.provider" required placeholder="DMIT、绿云…"></label><label class="full-field">主机地址<input v-model="editing.address" placeholder="留空由 Agent 回报 IP，也可手动填写"></label></div><h3>主机套餐与流量</h3><HostTrafficFields :draft="editing.billing" :available="editing.traffic?.interfaces_available"/><p class="muted">地址用于识别主机。Agent 主动连接控制端；没有公网 IPv4 也可以接入。对外分享地址在协议配置中设置。</p></div><div class="modal-footer"><button type="button" class="secondary" @click="editing=null">取消</button><button class="primary" :disabled="busy">{{editing.id?'保存修改':'保存并生成接入命令'}}</button></div></form></div>
<div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="删除主机"><div class="form-content"><h2>删除 {{removing.name}}？</h2><p>此操作会停止并清理远端 Agent、托管内核与配置，并删除后台对此主机的部署及流量数据。控制面、数据库、审计和其他软件会保留。离线主机等待回执；需要 Agent 0.12.0 的受控卸载器。跨主机链式 / FRP 依赖需要先解除。</p><p v-if="error" role="alert" class="error">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="remove">确认删除</button></div></section></div>
</template>

<style scoped>.server-card{padding:16px}.server-heading{gap:10px}.server-title{display:flex;align-items:center;gap:10px;min-width:0}.server-title h3{margin:0;font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.server-title p{margin:2px 0 0;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.server-icon{width:36px;height:36px;font-size:20px;flex:none}.server-heading>.status{flex:none;font-size:10px}.server-meta{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 2px;color:var(--muted);font-size:12px}.server-meta span+span{border-left:1px solid var(--border);padding-left:8px}.host-control-origin{display:block;margin:5px 0;font-size:12px}.host-quota{margin:10px 0 0;padding:10px;border:1px solid var(--border);border-radius:8px}.quota-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px}.host-quota strong{font-size:19px}.host-quota small{display:block;font-size:12px;line-height:1.65;color:var(--muted)}.host-quota progress{width:100%;height:4px;accent-color:var(--accent);margin:7px 0}.server-actions{gap:5px;margin-top:12px;padding-top:10px}.server-actions .primary{margin-bottom:2px}.single-column-editor{width:min(532px,96vw)}.single-column-editor .fields{grid-template-columns:minmax(0,1fr);gap:14px}</style>
